package com.mycompany.sistemacontable.vista; import com.mycompany.sistemacontable.servicio.GeneradorReportesService; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.io.File;
public class PanelReportes extends JPanel {private final GeneradorReportesService s=new GeneradorReportesService();private final JComboBox<String> tipos=new JComboBox<>(new String[]{"Balance General","Estado de Resultados","Balance de Comprobación","Libro Diario","Libro Mayor","Auxiliares","IVA"});private final JTable tabla=new JTable();private GeneradorReportesService.Reporte actual;public PanelReportes(){setLayout(new BorderLayout(10,10));setBorder(BorderFactory.createEmptyBorder(25,30,30,30));JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT));JLabel l=new JLabel("Generador de reportes");l.setFont(new Font("Segoe UI",Font.BOLD,26));JButton g=new JButton("Generar"),x=new JButton("Exportar Excel"),pdf=new JButton("Exportar PDF");p.add(l);p.add(tipos);p.add(g);p.add(x);p.add(pdf);add(p,BorderLayout.NORTH);add(new JScrollPane(tabla),BorderLayout.CENTER);g.addActionListener(e->generar());x.addActionListener(e->exportar(true));pdf.addActionListener(e->exportar(false));generar();}private void generar(){try{actual=s.generar(tipos.getSelectedItem().toString());DefaultTableModel m=new DefaultTableModel(actual.columnas(),0){public boolean isCellEditable(int r,int c){return false;}};for(String[]r:actual.filas())m.addRow(r);tabla.setModel(m);}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}private void exportar(boolean excel){if(actual==null)generar();JFileChooser fc=new JFileChooser();fc.setSelectedFile(new File(actual.titulo().replace(' ','_')+(excel?".xlsx":".pdf")));if(fc.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try{if(excel)s.excel(actual,fc.getSelectedFile());else s.pdf(actual,fc.getSelectedFile());JOptionPane.showMessageDialog(this,"Reporte exportado correctamente.");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Error",0);}}}
